const assert = require('assert');
const { parseCsv } = require('../index');
assert.deepStrictEqual(parseCsv('a,b\n1,2'), [['a', 'b'], ['1', '2']]);
assert.deepStrictEqual(parseCsv('a,"b,c"'), [['a', 'b,c']]);
assert.deepStrictEqual(parseCsv('"he said ""hi""",x'), [['he said "hi"', 'x']]);
console.log('ok');
